function useData(path: string, enabled = true) {
  const [data, setData] = useState<any>(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(enabled);
  const [version, setVersion] = useState(0);
  const reload = useCallback(() => setVersion(v => v + 1), []);
  useEffect(() => {
    let current = true;
    if (!enabled) { setData(null); setLoading(false); return; }
    setLoading(true); setError('');
    void api(path).then(r => { if (current) setData(r); }).catch(e => { if (current) setError(errorText(e)); }).finally(() => { if (current) setLoading(false); });
    return () => { current = false; };
  }, [path, enabled, version]);
  return { data, error, loading, reload };
}
function useAction() {
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const run = async (fn: () => Promise<void>) => { if (busy) return; setBusy(true); setError(''); try { await fn(); } catch (e) { setError(errorText(e)); } finally { setBusy(false); } };
  return { busy, error, run };
}
