function scalarFields(value:any):Record<string,string|number|boolean> {
  return Object.fromEntries(Object.entries(value??{}).filter(([key,v])=> !['synthetic','wording_reviewed'].includes(key)&&['string','number','boolean'].includes(typeof v))) as Record<string,string|number|boolean>;
}
function EvidenceFields({value,onChange}:{value:string;onChange:(value:string)=>void}) {
  const {t}=useLive();let fields:Record<string,string|number|boolean>={};try{fields=scalarFields(JSON.parse(value));}catch{/* unresolved fields */}
  const labels:Record<string,[string,string]>={insurer:['保险公司','Insurer'],policy_number:['保单号','Policy number'],insured_name:['被保险人','Insured person'],start_date:['起始日期','Start date'],end_date:['结束日期','End date'],product_name:['产品名称','Product name'],destination:['目的地','Destination'],document_date:['文件日期（可选）','Document date (optional)'],total_amount:['金额（可选）','Amount (optional)'],currency:['币种（可选）','Currency (optional)']};
  const editable={...fields,document_date:fields.document_date??'',total_amount:fields.total_amount??'',currency:fields.currency??''};
  return <><p className="live-muted">{t('仅显示可核对的文字与数值；空白不会视为已验证。材料内容仍以原件为准。','Review text and numeric facts. Blanks remain unverified; original evidence governs.')}</p><div className="live-fields-grid">{Object.entries(editable).map(([key,v])=><Field key={key} label={labels[key]?t(...labels[key]):key}><input value={String(v)} onChange={e=>onChange(JSON.stringify({...editable,[key]:e.target.value}))}/></Field>)}</div></>;
}
