export function PolicyPage() {
  const { id } = useParams(); const { user, t } = useLive(); const resource = useData(`/policies/${id}`, !!user); const action = useAction();
  const policy: Policy | null = resource.data; const navigate = useNavigate(); const [deleteRequested, setDeleteRequested] = useState(false);
  const [fields, setFields] = useState<Record<string, string>>({}); const [checked, setChecked] = useState(false); const [saved, setSaved] = useState(false);
  useEffect(() => { if (!policy) return; const data: Record<string, string> = {}; ['title','insurer','policy_number','insured_name','start_date','end_date','family','destination','benefits'].forEach(k => { data[k] = policyValue(policy,k); }); setFields(data); setChecked(false); }, [policy]);
  const labels: [string,string,string][] = [['title','产品名称','Product name'],['insurer','保险公司','Insurer'],['policy_number','保单号','Policy number'],['insured_name','被保险人','Insured person'],['start_date','生效日期','Start date'],['end_date','结束日期','End date'],['family','保险类别（请核对自动分类）','Insurance family (check the extracted category)'],['destination','旅行目的地','Destination'],['benefits','保障项目（每行一项）','Benefits (one per line)']];
  const save = () => void action.run(async () => { const benefits = policy && fields.benefits === policyValue(policy,'benefits') ? policy.fields.benefits : fields.benefits.split('\n').map(value=>value.trim()).filter(Boolean); await api(`/policies/${id}`, json('PATCH',{ fields: { ...fields, benefits }, confirmed: true })); setSaved(true); resource.reload(); });
  return <><PageTitle title={t('核对保单与条款', 'Review policy & wording')} action={<Link to="/" className="live-text-button">{t('返回首页', 'Back home')}</Link>} /><RequireAccount><ErrorBox error={resource.error} />{resource.loading ? <Loading /> : policy ? <><Section title={policy.title || t('待确认保单', 'Policy awaiting review')}><span className={`live-badge ${policy.confirmed ? 'success' : 'warning'}`}>{policy.confirmed ? t('关键资料已确认', 'Critical facts confirmed') : t('尚未确认 · 个性化结论受限', 'Unconfirmed · personalized guidance limited')}</span><p className="live-muted">{t('OCR 只是提取建议。请对照原文件核对，空白字段不能靠确认变成证据。', 'OCR provides candidate facts. Check the source; confirmation cannot turn missing facts into evidence.')}</p><div className="live-actions"><Link className="btn-secondary" to={`/ask?policy=${policy.id}`}>{t('询问这份保单', 'Ask about this policy')}</Link><Link className="btn-secondary" to={`/claims?policy=${policy.id}`}>{t('准备理赔', 'Prepare claim')}</Link></div></Section><Section title={t('关键资料', 'Critical facts')}><div className="live-fields-grid">{labels.map(([key,zh,en]) => <Field key={key} label={t(zh,en)}>{key === 'family' ? <select value={fields[key]||'other'} onChange={e=>{setFields(f=>({...f,family:e.target.value}));setChecked(false);setSaved(false);}}>{Object.entries(familyNames).map(([value,label])=><option key={value} value={value}>{t(...label)}</option>)}</select> : key === 'benefits' ? <textarea rows={4} value={fields[key] ?? ''} onChange={e => { setFields(f=>({...f,[key]:e.target.value})); setChecked(false); setSaved(false); }} /> : <input type={key.endsWith('date') ? 'date' : 'text'} value={fields[key] ?? ''} onChange={e => { setFields(f=>({...f,[key]:e.target.value})); setChecked(false); setSaved(false); }} />}</Field>)}</div><label className="live-checkbox"><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)} /><span>{t('我已对照原文件核对上述关键资料。', 'I checked these critical facts against the original document.')}</span></label><ErrorBox error={action.error} />{saved ? <Notice tone="success">{t('资料已保存；受影响的旧分析与确认需要重新核对。', 'Facts saved. Affected prior analysis and confirmations need review.')}</Notice> : null}<button className="btn-primary" disabled={!checked || action.busy} onClick={save}>{t('确认并保存', 'Confirm & save')}</button></Section><PolicyInsights policy={policy} onChange={resource.reload}/><Section title={t('原始文件与出处', 'Original documents & sources')}>{(policy.documents?.length ? policy.documents : [{id:policy.document_id,name:policy.title,kind:'policy'}]).map(doc=><div className="live-list-row" key={doc.id}><div><strong>{doc.name}</strong><p>{doc.kind} · {doc.ocr_status ?? ''}</p></div><Link className="btn-secondary btn-compact" to={`/documents/${doc.id}`}>{t('查看来源', 'View source')}</Link></div>)}<Link className="live-text-button" to={`/upload?policy=${policy.id}`}>{t('添加其他文件 →', 'Add another document →')}</Link><button className="live-text-button live-danger" onClick={()=>setDeleteRequested(true)}>{t('删除此保单及关联原件', 'Delete policy and linked originals')}</button>{deleteRequested?<Notice tone="warning">{t('确认删除此保单、关联原件与检索内容？已有准备包也可能失效，此操作无法在界面恢复。','Delete this policy, linked originals and retrieval content? Derived packages may be revoked. This cannot be restored in this interface.')}<div className="live-actions"><button className="btn-secondary" disabled={action.busy} onClick={()=>void action.run(async()=>{await api(`/policies/${id}`,{method:'DELETE'});navigate('/');})}>{t('确认删除','Confirm delete')}</button><button className="live-text-button" onClick={()=>setDeleteRequested(false)}>{t('保留','Keep')}</button></div></Notice>:null}</Section></> : null}</RequireAccount></>;
}

export function SourcePage() {
  const { id } = useParams(); const { user, t } = useLive(); const [params] = useSearchParams(); const resource = useData(`/documents/${id}`, !!user); const page = Number(params.get('page')) || 0;
  useEffect(()=>{if(page&&resource.data){document.getElementById(`page-${page}`)?.scrollIntoView({block:'start'});}},[page,resource.data]);
  return <><PageTitle title={t('查看文件来源', 'Document source')} /><RequireAccount><ErrorBox error={resource.error} />{resource.loading ? <Loading /> : resource.data ? <><Section title={resource.data.name ?? resource.data.document?.name ?? t('原始文件', 'Original document')}>{(resource.data.safety_warnings??[]).map((warning:string,i:number)=><Notice tone="warning" key={i}>{warning}</Notice>)}<a href={`/api/documents/${id}/file`} target="_blank" rel="noreferrer" className="btn-secondary">{t('打开原文件', 'Open original file')}</a><p className="live-muted">{t('下方为机器提取的页码文本。涉及金额、日期与排除责任时，请同时核对原件。', 'Page text is machine-extracted. Check the original for amounts, dates and exclusions.')}</p></Section>{(resource.data.pages ?? resource.data.document?.pages ?? []).map((p:any)=><Section key={p.page} title={`${t('第', 'Page')} ${p.page} ${t('页','')}`}><div id={`page-${p.page}`} className={`live-source ${page === p.page ? 'highlight' : ''}`}>{p.text || t('此页未提取出文字。', 'No text extracted from this page.')}</div></Section>)}</> : null}</RequireAccount></>;
}

interface ChatMessage { role:'user'|'assistant'; text:string; citations?:any[]; engine?:string; clarification?:{type:string;policy_id?:string;options?:{id:string;title:string}[]}; cards?:{type:string;path?:string;policy_id?:string}[];chips?:string[] }
export function ChatPage() {
  const { user, t, locale, health, setTrace } = useLive(); const [params] = useSearchParams();
  const policies = useData('/policies',!!user); const [policy,setPolicy]=useState(params.get('policy') ?? ''); const [draft,setDraft]=useState(''); const [messages,setMessages]=useState<ChatMessage[]>([]); const action=useAction(); const voice=useVoice(locale,setDraft); const tail=useRef<HTMLDivElement>(null);
  useEffect(()=>{tail.current?.scrollIntoView({behavior:'smooth',block:'end'});},[messages.length,action.busy]);
  const send=(event:FormEvent)=>{event.preventDefault();const text=draft.trim();if(!text||action.busy)return;setDraft('');setMessages(m=>[...m,{role:'user',text}]);void action.run(async()=>{const r=await api('/chat',json('POST',{message:text,policy_id:policy||null,locale}));setMessages(m=>[...m,{role:'assistant',text:r.answer,citations:r.citations,engine:r.engine,clarification:r.clarification,cards:r.cards,chips:r.chips}]);setTrace(r.trace??[]);});};
  const prompts=[t('我的保单对意外门诊有哪些条件？','What conditions apply to accidental outpatient treatment?'),t('哪些信息仍然缺失？','Which facts are still missing?'),t('如何比较适合我的保险？','How can I compare insurance for my needs?')];
  return <><PageTitle title={t('保障助手', 'Your insurance assistant')}>{t('让每个重要解释都能回到条款。你可以纠正、追问，或保留不确定。', 'Trace important explanations back to the policy. Correct, clarify or keep uncertainty visible.')}</PageTitle><RequireAccount><Section><Field label={t('本次问答使用的保单','Policy for this conversation')}><select value={policy} onChange={e=>{setPolicy(e.target.value);setMessages([]);voice.stop();}}><option value="">{t('未指定 · 助手会在需要时询问','Unspecified · the assistant will ask when needed')}</option>{(policies.data?.policies??[]).map((p:Policy)=><option key={p.id} value={p.id}>{p.title} {!p.confirmed?t('（待确认）','(unconfirmed)'):''}</option>)}</select></Field><p>{t('比较保险与紧急帮助无需先选择保单；个人保障问题需明确对应保单。','Comparisons and urgent help do not require a policy selection. Personal cover questions need the relevant policy.')}</p><span className="live-engine">{health?.ai?.configured?`${t('模型已配置','Model configured')}: ${health.ai.model}`:t('模型未配置 · 仅使用有出处的检索说明','Model not configured · sourced retrieval only')}</span></Section><div className="live-chat" aria-live="polite">{messages.length?messages.map((m,i)=><article className={`live-message ${m.role}`} key={i}><span className="live-message-role">{m.role==='user'?t('你','You'):'WeWise'}</span>{m.engine==='retrieval_only'&&m.citations?.length?<><p>{m.text.split('\n\n')[0]}</p><details><summary className="live-text-button">{t('查看完整检索摘录与说明','Read the full retrieved extracts and notice')}</summary><p className="live-source">{m.text}</p></details></>:<p>{m.text}</p>}{m.citations?.length?<div className="live-citations">{m.citations.map((c,j)=><details key={j}><summary>{t('来源','Source')} {j+1} · p.{c.page} · {String(c.quote??'').slice(0,80)}{String(c.quote??'').length>80?'…':''}</summary><p className="live-source">{c.quote}</p><Link to={`/documents/${c.document_id}?page=${c.page}`}>{t('打开原文件页码与全文','Open the original page & full text')} ↗</Link></details>)}</div>:null}{m.clarification?.type==='select_policy'?<div className="live-actions">{(m.clarification.options??[]).map(p=><button type="button" className="btn-secondary btn-compact" key={p.id} onClick={()=>{setPolicy(p.id);setDraft(messages.slice(0,i).reverse().find(v=>v.role==='user')?.text??'');}}>{t('使用这份保单','Use this policy')}: {p.title}</button>)}<Link to="/upload" className="live-text-button">{t('上传一份保单','Upload a policy')}</Link></div>:null}{m.clarification?.type==='confirm_policy'&&m.clarification.policy_id?<Link className="btn-secondary btn-compact" to={`/policies/${m.clarification.policy_id}`}>{t('核对并确认保单资料','Review & confirm the policy')}</Link>:null}{m.cards?.length?<div className="live-actions">{m.cards.map((card,j)=>card.type==='emergency'?<Link key={j} className="btn-secondary btn-compact" to="/emergency">{t('立即查看紧急与人类帮助','Open urgent & human help')}</Link>:card.type==='buying'?<Link key={j} className="btn-secondary btn-compact" to="/buy">{t('打开需求比较','Open needs comparison')}</Link>:card.type==='policy_review'&&card.policy_id&&m.clarification?.type!=='confirm_policy'?<Link key={j} className="btn-secondary btn-compact" to={`/policies/${card.policy_id}`}>{t('核对保单','Review policy')}</Link>:null)}</div>:null}{m.chips?.length?<div className="live-chips">{m.chips.map(chip=><button type="button" key={chip} onClick={()=>setDraft(chip)}>{chip}</button>)}</div>:null}{m.engine?<small>{t('实际回答引擎','Actual engine')}: {m.engine}</small>:null}</article>):<div className="live-chat-welcome"><AppIcon name="chat" size={40}/><h2>{t('保障、材料与下一步，一起看清楚','Make cover, evidence and next steps clearer.')}</h2><p>{t('不会把缺少证据的推测当成保障承诺，也不会代替保险公司作出赔付决定。','Missing evidence stays unresolved. We do not decide underwriting or payouts.')}</p><div className="live-chips">{prompts.map(p=><button key={p} onClick={()=>setDraft(p)}>{p}</button>)}</div></div>}{action.busy?<p className="live-muted" role="status">{t('正在检索保单与准备回答…','Retrieving evidence and answering…')}</p>:null}<div ref={tail}/></div><ErrorBox error={action.error}/><ErrorBox error={voice.error}/><form onSubmit={send} className="live-composer"><textarea aria-label={t('输入问题','Your question')} placeholder={t('问问保障、条款或下一步…','Ask about cover, wording or next steps…')} rows={2} value={draft} onChange={e=>setDraft(e.target.value)} /><div className="live-actions"><button type="button" className="btn-secondary btn-compact" disabled={!voice.canListen} onClick={voice.listening?voice.stop:voice.listen}><AppIcon name="mic" size={18}/>{voice.listening?t('停止聆听','Stop listening'):t('语音输入','Voice input')}</button><button type="button" className="btn-secondary btn-compact" disabled={!voice.canSpeak||!messages.some(m=>m.role==='assistant')} onClick={()=>voice.speaking?voice.stop():voice.speak([...messages].reverse().find(m=>m.role==='assistant')?.text??'')}>{voice.speaking?t('停止朗读','Stop audio'):t('朗读回复','Read reply')}</button><button className="btn-primary btn-compact" disabled={action.busy||!draft.trim()}>{t('发送','Send')}</button></div><small>{t('语音由浏览器提供，可能使用浏览器厂商服务。应用不保存原始音频；文字始终可用。','Speech uses browser capabilities and may use its provider services. This app does not store raw audio. Text always works.')}</small></form></RequireAccount></>;
}

const statusText = (status:string,t:(zh:string,en:string)=>string) => ({DRAFT:t('准备中 · 未提交','Draft · not submitted'),PREPARED_NOT_SUBMITTED:t('材料已准备 · 未提交保险公司','Prepared · not submitted to insurer')}[status] ?? status);
export function ClaimsPage() {
  const {user,t}=useLive(); const claims=useData('/claims',!!user);
  return <><PageTitle title={t('把理赔，拆成清楚的下一步','A clear next step for your claim')}>{t('实际准备与模拟保险公司进度分开记录，不把材料齐全当作已经批准。','Actual preparation and simulated insurer progress stay separate. Complete evidence does not mean approval.')}</PageTitle><RequireAccount><Section title={t('我的案件与待办','My cases and next actions')}><ErrorBox error={claims.error}/>{claims.loading?<Loading/>:(claims.data?.claims??[]).length?claims.data.claims.map((c:any)=><Link className="live-list-row live-link-row" key={c.id} to={`/claims/${c.id}`}><div><strong>{c.incident?.description||c.policy_title}</strong><p>{c.incident?.date} · {c.incident?.country}</p><span className="live-badge">{statusText(c.actual_status,t)}</span><p>{c.tracker?.actual?.next_action}</p>{c.tracker?.insurer_simulation?.receipt_reference?<span className="live-badge warning">{t('另有合成保险公司模拟','Separate synthetic insurer simulation')}</span>:null}</div><AppIcon name="chevron"/></Link>):<Empty>{t('还没有理赔准备记录。','No claim preparations yet.')}</Empty>}</Section><ClaimStart/></RequireAccount></>;
}

function IncidentEditFields({value,onChange,family,benefit,onBenefitChange}:{value:any;onChange:(value:any)=>void;family:string;benefit:string;onBenefitChange:(value:string)=>void}) {
  const {t}=useLive(); const library=useData(`/incidents?family=${encodeURIComponent(family)}`);
  const change=(key:string,next:string|boolean)=>onChange({...value,[key]:next});
  return <><div className="live-fields-grid">
    <Field label={t('事故日期','Incident date')}><input required type="date" value={value.date??''} onChange={e=>change('date',e.target.value)}/></Field>
    <Field label={t('城市','City')}><input value={value.city??''} onChange={e=>change('city',e.target.value)}/></Field>
    <Field label={t('事故所在国家','Incident country')}><select value={value.country??'Other'} onChange={e=>change('country',e.target.value)}><option value="Japan">{t('日本','Japan')}</option><option value="China">{t('中国','China')}</option><option value="Other">{t('其他 · 人工核对','Other · manual review')}</option>{value.country&&!['Japan','China','Other'].includes(value.country)?<option value={value.country}>{value.country}</option>:null}</select></Field>
    <Field label={t('申请的事故 / 给付类别','Incident / benefit requested')}><select value={benefit} onChange={e=>{onBenefitChange(e.target.value);const item=(library.data?.items??[]).find((x:any)=>x.benefit===e.target.value);if(item)change('event_type',item.id);}}>{!(library.data?.items??[]).some((item:any)=>item.benefit===benefit)?<option value={benefit}>{t('当前记录的类别','Current recorded benefit')}</option>:null}{(library.data?.items??[]).map((item:any)=><option key={item.id} value={item.benefit}>{t(item.title_zh??item.title,item.title)}</option>)}</select></Field>
    <Field label={t('治疗类别','Treatment type')}><select value={value.treatment_type??'unknown'} onChange={e=>change('treatment_type',e.target.value)}><option value="outpatient">{t('门诊','Outpatient')}</option><option value="inpatient">{t('住院','Inpatient')}</option><option value="unknown">{t('不适用 / 待确认','Not applicable / unknown')}</option></select></Field>
    <Field label={t('申请人角色','Applicant role')}><select value={value.applicant_role??'insured'} onChange={e=>change('applicant_role',e.target.value)}><option value="insured">{t('被保险人本人','Insured person')}</option><option value="guardian">{t('监护人','Guardian')}</option><option value="authorized_representative">{t('获授权代理人','Authorized representative')}</option><option value="beneficiary">{t('受益人','Beneficiary')}</option></select></Field>
    <Field label={t('医院 / 机构（可选）','Hospital / provider (optional)')}><input value={value.hospital??''} onChange={e=>change('hospital',e.target.value)}/></Field>
    <Field label={t('费用（可选）','Expenses (optional)')}><input type="number" min="0" value={value.expenses??''} onChange={e=>onChange({...value,expenses:e.target.value===''?null:Number(e.target.value)})}/></Field>
    <Field label={t('币种','Currency')}><select value={value.currency??'JPY'} onChange={e=>change('currency',e.target.value)}>{['CNY','JPY','USD'].map(currency=><option key={currency}>{currency}</option>)}</select></Field>
    <Field label={t('联系电话（可选，仅用合成资料）','Contact phone (optional; synthetic only)')}><input value={value.contact_phone??''} onChange={e=>change('contact_phone',e.target.value)}/></Field>
  </div><ErrorBox error={library.error}/>{[['prior_reimbursement',t('已有其他报销','Prior reimbursement')],['disability',t('涉及伤残评定','Disability assessment involved')],['death',t('涉及身故申请','Death benefit application')],['minor',t('被保险人为未成年人','Insured person is a minor')]].map(([key,label])=><label key={key} className="live-checkbox"><input type="checkbox" checked={!!value[key]} onChange={e=>change(key,e.target.checked)}/><span>{label}</span></label>)}</>;
}

export function ClaimPage() {
  const {id}=useParams();const {user,t}=useLive();const navigate=useNavigate();const [deleteCase,setDeleteCase]=useState(false);const resource=useData(`/claims/${id}`,!!user);const action=useAction();const claim=resource.data;
  const [pending,setPending]=useState<any>(null);const [pendingFields,setPendingFields]=useState('{}');const [documentChecked,setDocumentChecked]=useState(false);const [factsChecked,setFactsChecked]=useState(false);const [preview,setPreview]=useState<any>(null);const [exportChecked,setExportChecked]=useState(false);const [exported,setExported]=useState<any>(null);const [note,setNote]=useState('');const [eventAt,setEventAt]=useState('');const [updateProvenance,setUpdateProvenance]=useState('user_reported');const [acknowledgement,setAcknowledgement]=useState<{id:string;name:string}|null>(null);
  const [editIncident,setEditIncident]=useState(false);const [incidentDraft,setIncidentDraft]=useState<any>({});const [benefitDraft,setBenefitDraft]=useState('outpatient_accident');
  useEffect(()=>{setFactsChecked(false);setPreview(null);setExportChecked(false);},[claim?.revision]);
  const upload=(file:File,category:string)=>void action.run(async()=>{const body=new FormData();body.append('file',file);body.append('kind','evidence');body.append('claim_id',id!);const r=await api('/documents',{method:'POST',body});const doc=r.document??r;setPending({document_id:doc.id,category,name:doc.name??file.name});setPendingFields(JSON.stringify(scalarFields(doc.extracted_fields??r.extracted_fields??{})));setDocumentChecked(false);resource.reload();});
  const resumeDocument=(documentId:string,category:string)=>void action.run(async()=>{const doc=await api(`/documents/${documentId}`);setPending({document_id:doc.id,category,name:doc.name});setPendingFields(JSON.stringify(scalarFields(doc.extracted_fields)));setDocumentChecked(false);});
  const confirmDocument=()=>void action.run(async()=>{const fields=scalarFields(JSON.parse(pendingFields));await api(`/claims/${id}/evidence/${pending.document_id}`,json('PUT',{category:pending.category,confirmed:true,fields}));setPending(null);resource.reload();});
  const generateForm=()=>void action.run(async()=>{const r=await api(`/claims/${id}/generate-form`,json('POST',{}));setPending({document_id:r.document_id,category:'claim_form',name:t('生成的理赔申请草稿','Generated claim application draft')});setPendingFields('{}');setDocumentChecked(false);resource.reload();});
  const confirmFacts=()=>void action.run(async()=>{await api(`/claims/${id}/confirm`,json('POST',{revision:claim.revision,confirmed_fields:['date','country','description','treatment_type',...(claim.incident?.english_summary?['english_summary']:[])],confirmed:true}));setFactsChecked(false);resource.reload();});
  const getPreview=(mode='prepared',exportAction='export_claim_package')=>void action.run(async()=>{const r=await api(`/claims/${id}/preview`,json('POST',{mode,action:exportAction,recipient:'User download only'}));const kit=exportAction==='export_crossborder_kit'?await api(`/claims/${id}/crossborder-kit`):null;setPreview({...r,kit});setExportChecked(false);});
  const exportPackage=()=>void action.run(async()=>{const r=await api(`/claims/${id}/export`,json('POST',{token:preview.token,confirmed:true}));setExported(r);setPreview(null);setExportChecked(false);resource.reload();});
  const updateIncident=(e:FormEvent)=>{e.preventDefault();void action.run(async()=>{await api(`/claims/${id}`,json('PATCH',{incident:incidentDraft,benefit:benefitDraft,expected_revision:claim.revision}));setEditIncident(false);setExported(null);resource.reload();});};
  const missing=(claim?.checklist??[]).filter((item:any)=>item.required&&item.missing);
  return <><PageTitle title={t('理赔准备工作台','Claim preparation workspace')} action={<Link to="/claims" className="live-text-button">{t('所有记录','All cases')}</Link>}/><RequireAccount><ErrorBox error={resource.error}/><ErrorBox error={action.error}/>{resource.loading&&!claim?<Loading/>:claim?<>
    <ClaimTracker claim={claim} reload={resource.reload}/><Section title={t('你的实际案件','Your actual case')} action={<span className="live-badge">{statusText(claim.actual_status,t)}</span>}><p><strong>{claim.incident?.description}</strong></p><p className="live-muted">{claim.incident?.date} · {claim.incident?.city} · {claim.incident?.country} · {claim.incident?.treatment_type==='inpatient'?t('住院','Inpatient'):claim.incident?.treatment_type==='outpatient'?t('门诊','Outpatient'):t('治疗类型待确认','Treatment unspecified')}</p><Notice>{t('本应用尚未向保险公司提交。下面的模拟进度与真实准备状态分开保存。','This app has not submitted to an insurer. Simulated progress is stored separately from actual preparation.')}</Notice><div className="live-actions"><Link to={`/policies/${claim.policy_id}`} className="live-text-button">{t('查看关联保单','View policy')}</Link><button className="live-text-button" onClick={()=>{setIncidentDraft({...claim.incident});setBenefitDraft(claim.benefit);setEditIncident(!editIncident);}}>{t('更正事故资料','Correct incident facts')}</button><Link to="/emergency" className="live-text-button">{t('紧急与语言帮助','Urgent & language help')}</Link></div>{editIncident?<form className="live-form" onSubmit={updateIncident}><IncidentEditFields value={incidentDraft} onChange={setIncidentDraft} family={claim.policy_family??'travel'} benefit={benefitDraft} onBenefitChange={setBenefitDraft}/><Field label={t('事故描述','Description')}><textarea value={incidentDraft.description??''} onChange={e=>setIncidentDraft((d:any)=>({...d,description:e.target.value}))}/></Field><label className="live-checkbox"><input type="checkbox" checked={!!incidentDraft.police_involved} onChange={e=>setIncidentDraft((d:any)=>({...d,police_involved:e.target.checked}))}/><span>{t('警方参与本次事件','Police were involved')}</span></label><label className="live-checkbox"><input type="checkbox" checked={!!incidentDraft.third_party_involved} onChange={e=>setIncidentDraft((d:any)=>({...d,third_party_involved:e.target.checked}))}/><span>{t('本次事件涉及第三方','A third party was involved')}</span></label><Field label={t('已核对的英文摘要（可选，原文仍保留）','Reviewed English summary (optional; original retained)')}><textarea rows={4} value={incidentDraft.english_summary??''} onChange={e=>setIncidentDraft((d:any)=>({...d,english_summary:e.target.value}))}/></Field><Notice tone="warning">{t('更正会使受影响的材料确认、分享预览与旧准备包失效。','Corrections invalidate affected confirmations, action previews and prepared packages.')}</Notice><button className="btn-primary" disabled={action.busy}>{t('保存更正','Save corrections')}</button></form>:null}</Section>
    <Section title={t('1 · 确认事故资料','1 · Confirm incident facts')}><label className="live-checkbox"><input type="checkbox" checked={factsChecked} onChange={e=>setFactsChecked(e.target.checked)}/><span>{t('我已核对本次事故日期、地点、经过及适用的治疗类别。','I checked the incident date, location, description and applicable treatment type.')}</span></label><button className="btn-secondary" disabled={!factsChecked||action.busy} onClick={confirmFacts}>{t('确认当前版本','Confirm current version')}</button>{claim.confirmed_revision===claim.revision?<span className="live-badge success">{t('当前版本已确认','Current revision confirmed')}</span>:null}</Section>
    <div id="claim-documents"/><Section title={t('2 · 逐项准备与核对文件','2 · Prepare and review documents')} action={<span className={`live-badge ${missing.length?'warning':'success'}`}>{missing.length?t(`缺少 ${missing.length} 项`,`Missing ${missing.length}`):t('所需文件已核对','Required evidence reviewed')}</span>}><p className="live-muted">{t('只有实际上传并由你核对的材料才计入完成。上传不等于证据已被保险公司接受。','Only uploaded, user-reviewed documents count. Uploading does not mean insurer acceptance.')}</p>{(claim.checklist??[]).map((item:any)=><div className="live-checklist-row" key={item.category}><div className="live-checklist-copy"><AppIcon name={item.missing?'file':'check'} size={22}/><div><strong>{item.label}</strong><p>{item.required?t('必需','Required'):item.conditional?t('按条件适用','Conditional'):t('可选','Optional')} · {item.missing?t('待补充 / 待核对','Missing / needs review'):t('已核对','Reviewed')}</p>{item.description?<small>{item.description}</small>:null}{(item.accepted_document_ids??[]).map((docId:string)=><Link className="live-text-button" key={docId} to={`/documents/${docId}`}>{t('查看已保存文件','View saved document')}</Link>)}{(item.uploaded_document_ids??[]).filter((docId:string)=>!(item.accepted_document_ids??[]).includes(docId)).map((docId:string)=><button className="live-text-button" disabled={action.busy} key={docId} onClick={()=>resumeDocument(docId,item.category)}>{t('审核已上传文件','Review uploaded file')}</button>)}</div></div><label className="live-file-button">{t('上传文件','Upload file')}<input type="file" accept=".pdf,.jpg,.jpeg,.png,.txt" disabled={action.busy} onChange={e=>{const f=e.target.files?.[0];if(f)upload(f,item.category);e.target.value='';}}/></label></div>)}<div className="live-actions"><button className="btn-secondary" disabled={action.busy} onClick={generateForm}>{t('生成申请表草稿','Generate application draft')}</button><Link to={`/capture?claim=${id}`} className="btn-secondary">{t('拍摄并选择上传','Capture evidence')}</Link></div></Section>
    {pending?<Section title={t('审核刚上传的文件','Review uploaded document')}><p><strong>{pending.name}</strong> · {pending.category}</p><Link target="_blank" to={`/documents/${pending.document_id}`} className="btn-secondary">{t('先查看原件与提取文本','View original & extracted text')}</Link><EvidenceFields value={pendingFields} onChange={value=>{setPendingFields(value);setDocumentChecked(false);}}/><label className="live-checkbox"><input type="checkbox" checked={documentChecked} onChange={e=>setDocumentChecked(e.target.checked)}/><span>{t('我已查看文件、确认材料分类并核对相关字段。','I reviewed the file, its category and relevant extracted facts.')}</span></label><div className="live-actions"><button className="btn-primary" disabled={!documentChecked||action.busy} onClick={confirmDocument}>{t('确认该份材料','Confirm this document')}</button><button className="btn-secondary" onClick={()=>setPending(null)}>{t('稍后审核','Review later')}</button></div></Section>:null}
    {claim.prescreen?<Section title={t('条款预检查 · 不是赔付决定','Wording pre-check · not a payout decision')}><p>{resultNames[claim.prescreen.result]?t(...resultNames[claim.prescreen.result]):claim.prescreen.summary??claim.prescreen.result}</p>{(claim.prescreen.checks??[]).map((c:any,i:number)=><div className="live-list-row" key={i}><span>{checkNames[c.id]?t(...checkNames[c.id]):c.label??c.check??c.name??c.id}</span><strong>{resultNames[c.status]?t(...resultNames[c.status]):c.message??c.result??c.status}<small>{c.detail}</small></strong></div>)}<Notice>{t('仍需由保险公司审核原始材料、事故事实与全部适用条款。','The insurer must still assess original evidence, incident facts and all applicable wording.')}</Notice>{claim.prescreen.notice?<Notice tone="warning"><strong>{t('此条款的通知与协助要求 · 原始核对说明','Notification & assistance requirements · reviewed source notice')}</strong><p lang="en">{claim.prescreen.notice}</p><p>{t('请同时核对自己已签发保单中的通知与事先授权要求，紧急就医不要等待材料。','Check the notification and pre-authorization requirements of your issued policy. Do not delay urgent care for documents.')}</p>{(claim.prescreen.sources??[]).map((source:any,i:number)=><a key={i} className="live-text-button" href={source.url} target="_blank" rel="noreferrer">{t('核对原始条款','Check the original wording')} · {source.section}</a>)}</Notice>:null}</Section>:null}
    <Section title={t('3 · 审核导出内容','3 · Review and export')}><p>{t('导出仅下载到你的设备，不发送给任何保险公司或代理。','Export downloads to your device. It sends nothing to an insurer or agent.')}</p><div className="live-actions"><button className="btn-primary" disabled={action.busy||missing.length>0||claim.confirmed_revision!==claim.revision} onClick={()=>getPreview()}>{t('预览完整准备包','Preview prepared package')}</button><button className="btn-secondary" disabled={action.busy} onClick={()=>getPreview('draft')}>{t('预览未完成草稿','Preview incomplete draft')}</button><button className="btn-secondary" disabled={action.busy} onClick={()=>getPreview('draft','export_crossborder_kit')}>{t('预览跨境协助包','Preview cross-border kit')}</button></div>{missing.length?<p className="live-warning-text">{t('仍有必需材料缺失；完整准备包已锁定，草稿会明确标示缺项。','Required evidence is missing. The complete package is locked; drafts identify missing items.')}</p>:null}{preview?<div className="live-review"><h3>{t('确认本次操作','Confirm this action')}</h3><p><strong>{t('接收方：仅本人下载','Recipient: user download only')}</strong></p><p>{preview.disclosure}</p><ReviewSummary payload={preview.payload}/>{preview.kit?<><h3>{t('跨境联系与沟通资料','Cross-border contacts & communication')}</h3><p className="live-source">{preview.kit.english_summary}</p><Notice>{preview.kit.translation_notice}</Notice>{(preview.kit.contacts??[]).map((c:any)=><div className="live-list-row" key={c.id}><div><strong>{c.name}</strong><p>{c.number}</p></div><a className="live-text-button" href={c.source_url} target="_blank" rel="noreferrer">{t('官方来源','Official source')}</a></div>)}{(preview.kit.official_forms??[]).map((f:any,i:number)=><a key={i} className="live-text-button" href={f.url??f.source_url} target="_blank" rel="noreferrer">{f.label??f.title??f.name}</a>)}</>:null}<label className="live-checkbox"><input type="checkbox" checked={exportChecked} onChange={e=>setExportChecked(e.target.checked)}/><span>{t('我已核对当前案件资料和文件清单，同意导出此版本。','I reviewed these case facts and documents and approve exporting this version.')}</span></label><button className="btn-primary" disabled={!exportChecked||action.busy} onClick={exportPackage}>{t('确认并生成下载','Confirm & generate download')}</button></div>:null}{exported?<Notice tone="success"><strong>{t('文件已生成 · 仍未向保险公司提交','Files generated · still not submitted to insurer')}</strong><div className="live-actions"><a className="btn-secondary" href={exported.pdf_url} target="_blank" rel="noreferrer">PDF</a><a className="btn-secondary" href={exported.zip_url} download>ZIP</a></div></Notice>:null}</Section>
    {(claim.exports??[]).length?<Section title={t('已保存的导出版本','Saved export versions')}><Notice>{t('这是导出时的资料快照，可能早于当前修改。下载不代表已提交或保险公司已接收。','These are snapshots at export time and may predate current corrections. Downloading does not establish submission or insurer receipt.')}</Notice>{claim.exports.map((item:any)=><div className="live-list-row" key={item.id}><div><strong>{item.mode==='prepared'?t('已核对的准备包 · 未提交','Reviewed preparation · not submitted'):t('草稿 / 协助资料 · 未提交','Draft / assistance kit · not submitted')}</strong><p>{item.created_at}</p></div><div className="live-actions"><a className="btn-secondary btn-compact" href={item.pdf_url} target="_blank" rel="noreferrer">PDF</a>{item.zip_url?<a className="btn-secondary btn-compact" href={item.zip_url} download>ZIP</a>:null}</div></div>)}</Section>:null}
    {claim.official_channel_url?<Section title={t('下一步：由你通过官方渠道办理','Next: use the official insurer channel yourself')}><p>{t('先复核准备包，再核对保险公司的当前表格与提交要求。此链接不会自动提交，也不会附带你的资料。','Review your package and the insurer’s current forms and submission requirements. This link neither submits nor attaches your information.')}</p><a className="btn-secondary" href={claim.official_channel_url} target="_blank" rel="noreferrer">{t('查看保险公司官方理赔渠道','Open the official insurer claim channel')} ↗</a></Section>:null}
    <Section title={t('实际进度记录','Actual case updates')}><Notice>{t('用户填报、上传回执和保险公司确认采用不同来源标签。无直连接口时，不会伪造保险公司确认。','User reports, uploaded acknowledgements and insurer confirmations have distinct provenance. There is no invented insurer confirmation.')}</Notice>{(claim.updates??[]).map((u:any)=> <div className="live-trace" key={u.id}><strong>{u.provenance==='acknowledgement_uploaded'?t('用户上传回执 · 未经保险公司核验','Acknowledgement uploaded · not insurer verified'):t('用户填报','User reported')}</strong><span>{u.event_at??u.created_at}</span><p>{u.note??u.text}</p>{u.document_id?<Link to={`/documents/${u.document_id}`} className="live-text-button">{t('查看用户上传的回执原件','View the user-uploaded acknowledgement')}</Link>:null}</div>)}<Field label={t('记录来源','Update source')}><select value={updateProvenance} onChange={e=>setUpdateProvenance(e.target.value)}><option value="user_reported">{t('用户填报','User reported')}</option><option value="acknowledgement_uploaded">{t('用户上传回执（未经保险公司核验）','Uploaded acknowledgement (not insurer verified)')}</option></select></Field>{updateProvenance==='acknowledgement_uploaded'?<><Notice>{t('仅保存你选择的合成回执及来源标签，不会将内容标为保险公司已确认。','Saves your selected synthetic acknowledgement with its provenance. It will not be labelled insurer-confirmed.')}</Notice><label className="live-file-button">{t('选择并保存合成回执','Choose & save a synthetic acknowledgement')}<input type="file" accept=".pdf,.png,.jpg,.jpeg,.txt" disabled={action.busy} onChange={e=>{const file=e.target.files?.[0];if(file)void action.run(async()=>{const body=new FormData();body.append('file',file);body.append('kind','evidence');body.append('claim_id',id!);const result=await api('/documents',{method:'POST',body});const document=result.document??result;setAcknowledgement({id:document.id,name:document.name});});e.target.value='';}}/></label>{acknowledgement?<Link to={`/documents/${acknowledgement.id}`} className="live-text-button">{t('核对刚上传的回执','Review uploaded acknowledgement')}: {acknowledgement.name}</Link>:null}</>:null}<Field label={t('事件发生时间（可选）','Event time (optional)')}><input type="datetime-local" value={eventAt} onChange={e=>setEventAt(e.target.value)}/></Field><Field label={t('记录说明','Update note')}><textarea rows={2} value={note} onChange={e=>setNote(e.target.value)}/></Field><button className="btn-secondary" disabled={action.busy||!note.trim()||(updateProvenance==='acknowledgement_uploaded'&&!acknowledgement)} onClick={()=>void action.run(async()=>{await api(`/claims/${id}/updates`,json('POST',{note,event_at:eventAt||'',provenance:updateProvenance,...(updateProvenance==='acknowledgement_uploaded'?{document_id:acknowledgement?.id}:{})}));setNote('');setEventAt('');setAcknowledgement(null);resource.reload();})}>{t('确认来源并保存记录','Confirm source & save update')}</button></Section>
    <Section title={t('管理案件资料','Manage case data')}><button className="live-text-button live-danger" onClick={()=>setDeleteCase(true)}>{t('删除案件与已保存证据','Delete case and saved evidence')}</button>{deleteCase?<Notice tone="warning">{t('这会移除案件、关联证据与生成的导出文件，无法在界面恢复。原始保单仍会保留。','This removes the case, linked evidence and generated exports and cannot be restored here. The original policy remains.')}<div className="live-actions"><button className="btn-secondary" disabled={action.busy} onClick={()=>void action.run(async()=>{await api(`/claims/${id}?confirmed=true`,{method:'DELETE'});navigate('/claims');})}>{t('确认删除案件','Confirm case deletion')}</button><button className="live-text-button" onClick={()=>setDeleteCase(false)}>{t('保留','Keep')}</button></div></Notice>:null}</Section>
  </>:null}</RequireAccount></>;
}

export function EmergencyPage() {
  const {t,locale,user,health}=useLive();const [translationConsent,setTranslationConsent]=useState(false);const emergency=useData('/emergency?country=Japan');const [situation,setSituation]=useState('');const [summary,setSummary]=useState('');const [reviewed,setReviewed]=useState(false);const [response,setResponse]=useState('');const action=useAction();const voice=useVoice(locale,setSituation);
  const reassurance=t('先慢慢呼吸。如果现场不安全，请先移动到安全位置。需要紧急医疗协助时，请直接联系当地紧急服务。不要为了收集保险材料延误就医。我们可以一步一步整理发生了什么。','Take a slow breath. If the scene is unsafe, move to a safe place if you can. Contact local emergency services for urgent medical help. Do not delay care to collect insurance evidence. We can work through what happened one step at a time.');
  const prepare=()=>void action.run(async()=>{if(user){const result=await api('/assistance-summary',json('POST',{text:situation,locale:'en',consent_external_processing:translationConsent}));setSummary(result.summary);setResponse(`${result.translated?t('英文翻译草稿，需要逐项核对。','English translation draft; review every fact.'):t('原始叙述未翻译，使用沟通模板。','Original narrative is not translated; communication template only.')} ${result.notice} (${result.engine})`);}else{setSummary(`USER-REVIEWED ASSISTANCE NOTE — NOT CLINICALLY VERIFIED\nユーザー確認用サポートメモ\n\nOriginal user narrative (retained verbatim; not translated):\n${situation}\n\nPlease arrange language assistance if needed. Policy coverage has not been verified. No provider has received this note.`);setResponse(t('访客模式使用沟通模板。原始叙述保持原文，未自动翻译或核实。','Guest mode uses a communication template. Original words are not translated or verified.'));}setReviewed(false);});
  const download=()=>{const blob=new Blob([summary],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='wewise-reviewed-assistance-summary.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  return <><PageTitle eyebrow={t('无需登录 · 你随时可以直接找人','NO LOGIN REQUIRED · HUMAN HELP IS ALWAYS AN OPTION')} title={t('先照顾好你，再整理保险','Your wellbeing comes first')}>{t('这不是急救诊断或紧急调度服务。AI 对话不是获得帮助的前置步骤。','This is not emergency diagnosis or dispatch. An AI conversation is never required before seeking help.')}</PageTitle><VoiceAssistance/><ErrorBox error={emergency.error}/><Section title={t('日本 · 直接联系真实服务','Japan · contact real services')}><p className="live-muted">{t('拨号会打开你设备的电话应用；本平台不会拨打或转接。','Dial links open your device phone app. We do not place or transfer calls.')}</p>{emergency.loading?<Loading/>:(emergency.data?.contacts??[]).map((c:any)=><div className="live-contact" key={c.id}><div><strong>{c.name}</strong><p>{c.role==='local_emergency'?t('当地紧急服务','Local emergency services'):t('游客协助服务','Visitor assistance')}</p><a href={c.source_url} target="_blank" rel="noreferrer">{t('官方来源','Official source')}</a><small>{t('资料核对日期','Source checked')}: {c.verified_on}</small></div><a className="btn-primary" href={c.dial_uri??`tel:${c.number}`}>{c.number}</a></div>)}<Notice>{t('保险公司协助电话必须从你的保单或官方渠道核对。平台不能保证任何供应商已接收摘要或同意费用安排。','Verify insurer assistance contacts from your policy or its official channel. We cannot promise receipt of a summary or payment arrangements.')}</Notice></Section><Section><p className="live-reassurance">{reassurance}</p><div className="live-actions"><button className="btn-primary" disabled={!voice.canSpeak} onClick={()=>voice.speak(reassurance)}><AppIcon name="phone" size={18}/>{t('听一段安心引导','Listen to calming guidance')}</button><button className="btn-secondary" onClick={voice.stop}>{t('停止 / 静音','Stop / mute')}</button></div><p className="live-muted">{t('浏览器语音朗读，不是电话通话；没有实时转接或派遣。','Browser speech, not a telephone call. No live transfer or dispatch.')}</p></Section><Section title={t('出险后，先做这些','After an incident')}><ol className="live-steps"><li>{t('优先确保安全、就医与寻求人类帮助。','Prioritize safety, treatment and human help.')}</li><li>{t('在安全且允许的情况下记录时间、地点与经过。','When safe and permitted, record time, place and what happened.')}</li><li>{t('保存病历、诊断记录、原始费用票据与旅行证明。','Keep treatment records, clinician-recorded diagnoses, original bills and travel evidence.')}</li><li>{t('查看保单中的通知、事先授权与协助服务要求。','Check notification, pre-authorization and assistance requirements in your wording.')}</li></ol></Section><Section title={t('中 / 英 / 日沟通卡片','Chinese / English / Japanese cards')}>{(emergency.data?.cards??[]).map((card:any,i:number)=><div className="live-language-card" key={i}><p lang="zh-CN">{card.zh}</p><p lang="en">{card.en}</p><p lang="ja"><strong>{card.ja}</strong></p><button className="live-text-button" disabled={!voice.canSpeak} onClick={()=>voice.speak(card.ja,'ja')}>{t('朗读日文','Read Japanese')}</button></div>)}{(emergency.data?.official_forms??[]).map((form:any,i:number)=><a className="live-text-button" href={form.url??form.source_url} target="_blank" rel="noreferrer" key={i}>{form.label??form.name??form.title}</a>)}</Section><Section title={t('你可以带走的协助摘要','An assistance summary you control')}><Field label={t('用自己的话描述情况（仅合成资料）','Describe the situation (synthetic details only)')}><textarea rows={4} value={situation} onChange={e=>{setSituation(e.target.value);setReviewed(false);}}/></Field>{user?<label className="live-checkbox"><input type="checkbox" checked={translationConsent} onChange={e=>setTranslationConsent(e.target.checked)}/><span>{health?.ai?.configured?t('我允许仅将上方合成叙述发送至已配置的模型服务，生成需要我复核的翻译草稿。','Send only this synthetic narrative to the configured model for a translation draft I will review.'):t('模型尚未配置。即使选择此项，也只会生成标明未翻译的原文模板。','No model is configured. Only a clearly untranslated original-text template can be generated.')}</span></label>:null}<div className="live-actions"><button className="btn-secondary" disabled={!voice.canListen} onClick={voice.listening?voice.stop:voice.listen}>{voice.listening?t('停止聆听','Stop listening'):t('语音输入','Voice input')}</button><button className="btn-primary" disabled={!situation.trim()||action.busy} onClick={prepare}>{t('准备摘要','Prepare summary')}</button></div><ErrorBox error={action.error}/><ErrorBox error={voice.error}/>{summary?<><p>{response}</p><Field label={t('可编辑摘要 · 不自动发送','Editable summary · not sent automatically')}><textarea rows={7} value={summary} onChange={e=>{setSummary(e.target.value);setReviewed(false);}}/></Field><label className="live-checkbox"><input type="checkbox" checked={reviewed} onChange={e=>setReviewed(e.target.checked)}/><span>{t('我已核对事实，决定自行下载并分享此摘要。','I reviewed the facts and choose to download and share this summary myself.')}</span></label><button className="btn-secondary" disabled={!reviewed} onClick={download}>{t('下载摘要','Download summary')}</button></>:null}</Section></>;
}

export function BuyPage() { return <BuyingJourney/>; }

export function MePage() {
  const {user,t,ready,refreshUser,openInspector}=useLive();const navigate=useNavigate();const action=useAction();const [register,setRegister]=useState(false);const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [name,setName]=useState('');const memories=useData('/memory',!!user);const audit=useData('/audit',!!user);const preferences=useData('/preferences',!!user);
  const [memoryKey,setMemoryKey]=useState('communication_preferences');const [memoryValue,setMemoryValue]=useState('');const [approved,setApproved]=useState(false);const [editId,setEditId]=useState('');const [editValue,setEditValue]=useState('');const [deleteMemory,setDeleteMemory]=useState('');
  const auth=(event:FormEvent)=>{event.preventDefault();void action.run(async()=>{await api(register?'/auth/register':'/auth/login',json('POST',{email,password,...(register?{display_name:name}: {})}));setPassword('');await refreshUser();});};
  const demo=()=>void action.run(async()=>{await api('/auth/demo',json('POST',{}));await refreshUser();navigate('/');});
  const addMemory=(event:FormEvent)=>{event.preventDefault();void action.run(async()=>{await api('/memory',json('POST',{key:memoryKey,value:memoryValue,approved:true,source:'user_approved'}));setMemoryValue('');setApproved(false);memories.reload();audit.reload();});};
  return <><PageTitle title={t(user?'我的私人空间':'欢迎来到 WeWise',user?'Your private workspace':'Welcome to WeWise')}>{t('你决定记住什么、保存什么、分享什么。','You decide what is remembered, saved and shared.')}</PageTitle>{user?<WorkspaceTools/>:null}<Section title={t('更多工具','More tools')}><div className="live-actions"><Link className="btn-secondary btn-compact" to="/visual"><AppIcon name="shield" size={18}/>{t('可选 3D 演示','Optional 3D demo')}</Link><Link className="btn-secondary btn-compact" to="/capture"><AppIcon name="scan" size={18}/>{t('拍摄证据','Capture evidence')}</Link><Link className="btn-secondary btn-compact" to="/about"><AppIcon name="info" size={18}/>{t('能力与来源','Capabilities & sources')}</Link><button type="button" className="btn-secondary btn-compact" onClick={openInspector}>{t('查看实际运行记录','Actual agent trace')}</button></div><a href="/?mode=simulator" className="live-text-button">{t('打开独立预设引导模拟器（所有办理均为模拟）','Open the separate guided simulator (all transactions simulated)')} ↗</a></Section><ErrorBox error={action.error}/>{!ready?<Loading/>:!user?<Section title={register?t('创建账户','Create account'):t('登录账户','Sign in')}><Notice>{t('仅使用合成资料。真实后端会保存你明确选择保存的文件与记忆。','Use synthetic data only. The working backend stores the files and memories you explicitly choose to save.')}</Notice><form onSubmit={auth} className="live-form">{register?<Field label={t('显示名称','Display name')}><input required value={name} onChange={e=>setName(e.target.value)}/></Field>:null}<Field label={t('邮箱','Email')}><input type="email" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)}/></Field><Field label={t('密码（至少 10 个字符）','Password (at least 10 characters)')}><input type="password" minLength={10} autoComplete={register?'new-password':'current-password'} required value={password} onChange={e=>setPassword(e.target.value)}/></Field><button className="btn-primary" disabled={action.busy}>{register?t('注册并登录','Register & sign in'):t('登录','Sign in')}</button><button type="button" className="live-text-button" onClick={()=>setRegister(!register)}>{register?t('已有账户？登录','Have an account? Sign in'):t('创建新账户','Create an account')}</button></form><div className="live-divider"/><button className="btn-secondary" disabled={action.busy} onClick={demo}>{t('创建私人合成资料演示空间','Start a private synthetic demo')}</button><small className="live-muted">{t('每次创建独立演示空间，资料与其他测试者隔离。仅使用合成资料；退出后请重新创建演示空间。','Each demo has separate documents and data. Use synthetic details only. After signing out, start a new demo workspace.')}</small></Section>:<><Section title={user.display_name||t('我的账户','My account')}><p>{user.email}</p><div className="live-actions"><Link to="/" className="btn-secondary">{t('我的保单与文件','My policies & files')}</Link><button className="live-text-button" disabled={action.busy} onClick={()=>void action.run(async()=>{await api('/auth/logout',json('POST',{}));await refreshUser();})}>{t('退出登录','Sign out')}</button></div></Section><Section title={t('我记住了什么','What I remember')}><p>{t('仅存储你批准的事实与偏好。原始医疗报告、财务报告和完整对话不会自动成为长期记忆。','Only facts and preferences you approve. Original medical or financial reports and full conversations are not automatically long-term memory.')}</p><ErrorBox error={memories.error}/>{memories.loading?<Loading/>:(memories.data?.memories??[]).length?(memories.data.memories as any[]).map(m=><div className="live-memory" key={m.id}><div><strong>{memoryNames[m.key]?t(...memoryNames[m.key]):m.key}</strong><small>{m.source} · {m.updated_at}</small></div>{editId===m.id?<><textarea aria-label={t('更正记忆内容','Correct memory')} value={editValue} onChange={e=>setEditValue(e.target.value)}/><div className="live-actions"><button className="btn-secondary btn-compact" disabled={action.busy||!editValue.trim()} onClick={()=>void action.run(async()=>{await api(`/memory/${m.id}`,json('PATCH',{value:editValue,approved:true}));setEditId('');memories.reload();audit.reload();})}>{t('确认更正','Approve correction')}</button><button className="live-text-button" onClick={()=>setEditId('')}>{t('取消','Cancel')}</button></div></>:<><p>{typeof m.value==='string'?m.value:JSON.stringify(m.value)}</p><div className="live-actions"><button className="live-text-button" onClick={()=>{setEditId(m.id);setEditValue(typeof m.value==='string'?m.value:JSON.stringify(m.value));}}>{t('编辑','Edit')}</button><button className="live-text-button live-danger" onClick={()=>setDeleteMemory(m.id)}>{t('删除','Delete')}</button></div></>}{deleteMemory===m.id?<Notice tone="warning">{t('删除此记忆并停止后续检索？原始保单文件需单独管理。','Delete this memory and remove it from future retrieval? Original policy files are managed separately.')}<div className="live-actions"><button className="btn-secondary btn-compact" disabled={action.busy} onClick={()=>void action.run(async()=>{await api(`/memory/${m.id}`,{method:'DELETE'});setDeleteMemory('');memories.reload();audit.reload();})}>{t('确认删除','Confirm delete')}</button><button className="live-text-button" onClick={()=>setDeleteMemory('')}>{t('保留','Keep')}</button></div></Notice>:null}</div>):<Empty>{t('还没有批准的长期记忆。','No approved memories yet.')}</Empty>}<form onSubmit={addMemory} className="live-form">{!preferences.data?.memory_enabled?<Notice tone="warning">{t('请先在下方开启批准记忆功能，再添加记忆。','Enable approved memory below before adding a fact.')}</Notice>:null}<Field label={t('记忆名称','Memory key')}><select value={memoryKey} onChange={e=>{setMemoryKey(e.target.value);setApproved(false);}}>{(memories.data?.supported_keys??['preferred_language','travel_preferences','budget_preferences','communication_preferences','accessibility_preferences']).map((key:string)=><option key={key} value={key}>{memoryNames[key]?t(...memoryNames[key]):key}</option>)}</select></Field><Field label={t('你希望记住的内容','What would you like remembered?')}><textarea required value={memoryValue} onChange={e=>{setMemoryValue(e.target.value);setApproved(false);}} placeholder={t('例如：喜欢简短中文说明，遇到专业术语时给例子。','Example: I prefer short explanations with concrete examples.')}/></Field><label className="live-checkbox"><input type="checkbox" checked={approved} onChange={e=>setApproved(e.target.checked)}/><span>{t('我批准将此事实保存为长期记忆，随时可编辑或删除。','I approve saving this fact as memory. I can edit or delete it anytime.')}</span></label><button className="btn-primary" disabled={!approved||!memoryValue.trim()||action.busy||!preferences.data?.memory_enabled}>{t('批准并保存记忆','Approve & save memory')}</button></form></Section><Section title={t('记忆偏好','Memory preferences')}><ErrorBox error={preferences.error}/><label className="live-checkbox"><input type="checkbox" checked={preferences.data?.memory_enabled??true} disabled={action.busy||!preferences.data} onChange={e=>void action.run(async()=>{await api('/preferences',json('PATCH',{memory_enabled:e.target.checked}));preferences.reload();audit.reload();})}/><span>{t('允许使用我批准的记忆进行个性化；关闭不会自动删除已保存记忆。','Use my approved memories for personalization. Turning this off does not automatically delete saved items.')}</span></label></Section><Section title={t('操作与分享记录','Action & sharing history')}><ErrorBox error={audit.error}/>{(audit.data?.events??[]).slice(0,30).map((event:any)=><div className="live-trace" key={event.id}><strong>{event.action}</strong><span>{event.created_at}</span><p>{event.entity_type} · {event.entity_id??'—'}</p></div>)}</Section></>}
  <Section title={t('保存与删除说明','Saving & deletion')}><p>{t('可先临时读取文件，再明确选择保存到保单或案件。未保存文件的访问权限在 24 小时后结束；当前存储的清理在访问、清理操作或服务启动时执行，并非保证到点立即物理删除。已保存资料保留至你删除；删除会移除当前原件与检索内容，并撤销相关准备包。下载副本和托管快照有独立的保留边界，本次仅使用合成资料。','Read a file temporarily, then explicitly choose whether to save it to a policy or case. Access to unsaved files ends after 24 hours; current-store purge runs on access, cleanup or service startup, rather than guaranteed physical deletion at that exact instant. Saved files remain until you delete them. Deletion removes current originals and retrieval content and revokes linked packages. Downloaded copies and hosting snapshots have separate retention boundaries. Use synthetic data only.')}</p><Link to="/about" className="live-text-button">{t('查看能力与限制','View capabilities & limits')}</Link></Section></>;
}

const AssetScene=lazy(()=>import('@/features/showcase/AssetScene'));
class OptionalSceneBoundary extends Component<{children:ReactNode;fallback:ReactNode},{failed:boolean}> {
  state={failed:false};
  static getDerivedStateFromError(){return {failed:true};}
  render(){return this.state.failed?this.props.fallback:this.props.children;}
}
export function VisualPage() {
  const {t}=useLive();const [index,setIndex]=useState(0);const drag=useRef(0);const [enabled,setEnabled]=useState(false);
  return <><PageTitle title={t('可选的 3D 资产概览','Optional 3D asset overview')}>{t('保留团队原有的视觉探索。实际保单仍以首页已保存资料为准。','The team’s original visual exploration. Your saved policy facts remain the portfolio source of truth.')}</PageTitle><Notice tone="warning">{t('视觉演示：通用模型与合成资产，不代表你已投保、受保金额或保险公司的认可。','Visual demonstration: generic models and synthetic assets, not proof of cover, insured values or insurer approval.')}</Notice><Section>{enabled?<OptionalSceneBoundary fallback={<div className="live-empty"><AppIcon name="shield" size={40}/><p>{t('此设备暂时无法显示 3D 场景。你的保单与其他功能仍可继续使用。','The 3D scene is unavailable on this device. Your policy cards and other features remain available.')}</p><Link to="/" className="btn-secondary">{t('查看保单卡片','View policy cards')}</Link></div>}><div className="live-visual-stage"><Suspense fallback={<Loading/>}><AssetScene index={index} drag={drag}/></Suspense></div></OptionalSceneBoundary>:<div className="live-empty"><AppIcon name="shield" size={60}/><p>{t('3D 场景仅在你选择时加载，需要 WebGL。','The 3D scene loads only on request and requires WebGL.')}</p><button className="btn-primary" onClick={()=>setEnabled(true)}>{t('打开 3D 演示','Load 3D demonstration')}</button></div>}<div className="live-chips">{[t('汽车','Car'),t('住宅','Home'),t('代步车','Scooter'),t('无人机','Drone')].map((name,i)=><button key={name} aria-pressed={index===i} onClick={()=>setIndex(i)}>{name}</button>)}</div></Section><Link to="/" className="btn-secondary">{t('返回真实保单卡片','Return to actual policy cards')}</Link></>;
}

export function CapturePage() { return <GuidedCapture/>; }
export function ReportPage() { return <ReportReview/>; }
export function IncidentLibraryPage() { return <IncidentLibrary/>; }

export function AboutPage() {
  const {t,health}=useLive();
  return <><PageTitle title={t('能力、来源与限制','Capabilities, sources & limits')}>{t('把能运行的功能与尚未接通的服务分清楚。','Separate working functionality from services that are not connected.')}</PageTitle><Section title={t('当前运行配置','Actual runtime configuration')}><dl className="live-facts"><dt>API</dt><dd>{health?.status??t('不可用','Unavailable')}</dd><dt>LLM</dt><dd>{health?.ai?.configured?health.ai.model:t('未配置 · 有出处的检索回退','Not configured · sourced retrieval fallback')}</dd><dt>OCR</dt><dd>{health?.ocr?.engine??'—'}</dd><dt>JEV</dt><dd>{health?.jev?.configured?'Configured':t('未配置 · 规则路由','Not configured · rules routing')}</dd><dt>{t('批准记忆','Approved memory')}</dt><dd>{health?.memory?.tencent_verified?t('腾讯记忆私有投影已接通；本地批准记录保留权威','Private Tencent projection connected; approved ledger remains authoritative'):t('当前部署使用私人批准记忆记录；腾讯服务未接通','Private approved-memory ledger; Tencent sidecar not connected here')}</dd><dt>{t('真实保险公司接口','Live insurer interface')}</dt><dd>{t('未连接','Not connected')}</dd></dl></Section><Section title={t('真实工作功能','Working application features')}><ul className="live-steps"><li>{t('账户、文件上传、实际提取结果与字段核对。','Accounts, file upload, actual extraction results and field review.')}</li><li>{t('基于获准保单材料的检索、出处与模型状态。','Retrieval over permitted policy evidence with citations and model status.')}</li><li>{t('按条件准备材料、版本确认、下载准备包。','Conditional evidence checklist, revision confirmation and package download.')}</li><li>{t('用户批准的记忆、编辑/删除、实际操作记录。','Approved memories, edit/delete controls and actual action history.')}</li><li>{t('浏览器支持时提供语音与相机；不支持时明确回退文字和文件选择。','Speech and camera where browser-supported, with explicit text/file alternatives.')}</li></ul><Notice>{t('这些功能操作的是合成测试资料；运行、可用性与模型接入状态以实际响应为准。','These features operate on synthetic test data. Actual responses determine runtime availability and model connectivity.')}</Notice></Section><Section title={t('明确模拟与后续功能','Explicit simulations & later work')}><p>{t('保险公司回执、审核时间线与代理回拨是独立模拟。没有真实销售、核保、出单、赔付、电话转接或紧急派遣。','Insurer receipts, processing timelines and agent callbacks are separate simulations. No real sales, underwriting, issuance, payouts, telephone transfers or emergency dispatch.')}</p><p>{t('长期规划：持牌合作、真实接口、家庭授权、更完整的产品规则库与正式部署的数据生命周期验证。','Roadmap: licensed partnerships, real integrations, family delegation, broader product rules and deployed data-lifecycle verification.')}</p></Section><Section title={t('参考来源','Reference sources')}><ul className="live-source-links"><li><a href="https://pts.allianz.com.cn/portal/resources/material/clauses/NLC_AXWL02_231.pdf" target="_blank" rel="noreferrer">{t('安联中国 · 境外旅行意外伤害保险 2023 条款','Allianz China · overseas travel accident wording (2023)')}</a></li><li><a href="https://www.japan.travel/en/plan/hotline/" target="_blank" rel="noreferrer">JNTO Japan Visitor Hotline</a></li><li><a href="https://www.webank.com/" target="_blank" rel="noreferrer">{t('微众银行官网 · 品牌视觉观察','WeBank official website · visual reference')}</a></li><li><a href="https://github.com/TencentCloud/TencentDB-Agent-Memory" target="_blank" rel="noreferrer">TencentDB Agent Memory</a></li><li><a href="https://mobbin.com/screens/f35fb2cc-a9f1-42ee-b8e2-889f5ab93b22" target="_blank" rel="noreferrer">Mobbin · Grab progress and next-action reference</a></li><li><a href="https://mobbin.com/flows/5cc9343b-62a9-411b-9742-36ebe3952238" target="_blank" rel="noreferrer">Mobbin · Lemonade claims interaction reference</a></li><li><a href="https://mobbin.com/flows/02caa2ab-a4c3-414a-be4e-3b3b06123c08" target="_blank" rel="noreferrer">Mobbin · State Farm document organization</a></li></ul><p className="live-muted">{t('此项目是独立黑客松概念，不是微众银行或保险公司正式发布的产品。官方标志保持原样，界面适配不代表授权合作。','Independent hackathon concept, not an official WeBank or insurer product. Unchanged official marks and visual adaptation do not establish a partnership.')}</p></Section></>;
}
